const asset=p=>typeof p==='string'&&/^Assets\/.+\.hbprefab\.json$/.test(p)&&!p.includes('..');
export function validPrefabLink(link,validateRows){return !!link&&link.version===1&&asset(link.asset)&&typeof link.root==='string'&&Array.isArray(link.baseline)&&link.baseline.every(o=>o&&!o.prefabLink)&&(!validateRows||validateRows(link.baseline))&&link.baseline.some(o=>o.id===link.root)&&link.ids&&typeof link.ids==='object'&&!Array.isArray(link.ids)&&link.baseline.every(o=>Object.hasOwn(link.ids,o.id))&&Object.values(link.ids).every(v=>typeof v==='string'&&v.length>0&&v.length<=160)&&new Set(Object.values(link.ids)).size===Object.values(link.ids).length&&(link.overrides===undefined||Array.isArray(link.overrides)&&link.overrides.every(c=>c&&typeof c.object==='string'&&Array.isArray(c.path)&&c.path.length<=32&&c.path.every(k=>(typeof k==='string'||Number.isInteger(k))&&!['__proto__','prototype','constructor'].includes(String(k)))))&&Array.isArray(link.conflicts)&&link.conflicts.every(c=>c&&typeof c.object==='string'&&Array.isArray(c.path)&&c.path.length<=32&&c.path.every(k=>(typeof k==='string'||Number.isInteger(k))&&!['__proto__','prototype','constructor'].includes(String(k))))&&(link.dependencies===undefined||Array.isArray(link.dependencies)&&link.dependencies.every(asset))&&(link.sourceRevision===undefined||typeof link.sourceRevision==='string'&&link.sourceRevision.length<=64);}
